  int ai_choice = 0;
  char buffer[100];
  int pos = scnprintf(buffer, 100, " Draw %d card", howmany);
  if (howmany == 1)
    pos = scnprintf(buffer, 100, " Draw a card");
  else
    {
      if (howmany < 1)
        return 0;
      pos += scnprintf(buffer + pos, 100 - pos, "s");
