			  ){
				if( mode && (mode & 1) ){
					instance->targets[1].player = get_toughness(p, c);
				}
				instance->targets[11].player = 1; //Otherwise "resolve_gfp_ability" won't trigger
				instance->damage_target_player = instance->damage_target_card = -1;
			}
