		if( mode && (mode & 1) && instance->targets[1].player > 0 ){
			gain_life(instance->targets[0].player, instance->targets[1].player);
		}
		if( mode && (mode & 2) ){
			if( do_dialog(instance->targets[0].player, player, card, -1, -1, " Draw a card\n Pass", 0) == 0 ){
