				&& (damage->damage_target_card != -1 || damage->damage_target_player != 1-player || damage_is_to_planeswalker(damage))){
				good = 0;
			}
			if ((mode & DDBM_MUST_BE_COMBAT_DAMAGE)
				&& !(damage->token_status & (STATUS_COMBAT_DAMAGE|STATUS_FIRST_STRIKE_DAMAGE))){
