    instance->targets[i].player = -1;
    if (cc == amount)
      break;
    result = instance->targets[i].card;
    if (result == -1)
      break;
    colors[cc++] = result & 3;
    instance->targets[i].card = -1;
  }
  for (int i = 0; i < amount; ++i)
  {
    int cpl = can_pay_life(player, 2);
    int abils[5] = {0, ((colors[i] & 1) && cpl) ? 1 : 0, colors[i] & 2,
