		  if (trigger_mode == RESOLVE_TRIGGER_DUH)
			trigger_mode = duh_mode(player) ? RESOLVE_TRIGGER_MANDATORY : RESOLVE_TRIGGER_OPTIONAL;

		  event_result |= trigger_mode;
		}
	  if (event == EVENT_RESOLVE_TRIGGER)
		return 1;
	}

  return 0;
}

