      (current_turn == affected_player || affected_player == ANYBODY) &&
      (is_what(player, card, TYPE_EFFECT) || !is_humiliated(player, card, AL_TRIG)))
  {
    for (int p = 0; p < 2; ++p)
    {
      for (int c = active_cards_count[p] - 1; c >= 0; --c)
