	  for (i = 0; i < num_cards_milled; ++i)
		if (is_what(-1, cards_milled[i].internal_card_id, TYPE_CREATURE))
		  {
			if (event == EVENT_TRIGGER)
			  {
				event_result |= RESOLVE_TRIGGER_AI(player);
				return;
			  }

			if (event == EVENT_RESOLVE_TRIGGER)
			  {
