	  if (when_a_card_is_put_into_graveyard_from_anywhere_but_library_do_something(player, card, event, 1-player, RESOLVE_TRIGGER_OPTIONAL, &test))
		{
		  iids[0] = trigger_cause;
		  num_creatures = 1;
