	  if ((land_can_be_played & LCBP_DURING_EVENT_CHANGE_TYPE_SECOND_PASS)
		  && cards_data[event_result].id != CARD_ID_MISHRAS_FACTORY
		  && cards_data[event_result].id != CARD_ID_ASSEMBLY_WORKER)
		return 0;

