				int iid = *loc2 & ~0x80000000;
				*loc2 = -1;
				if( check_rfg(player, cards_data[iid].id) ){
					play_card_in_exile_for_free(player, player, cards_data[iid].id);
				}
			}
		}
	}

	return 0;
}

