		int count = count_graveyard(player)-1;
		while( count > -1 ){
				if( cards_data[get_grave(player)[count]].id == get_id(player, card) ){
					backup_special[0] = turn_card_in_grave_face_down(player, count);
					backup_special[1] = count;
