          if (choice == 0)
          {
            generic_activated_ability(instance->targets[0].player, instance->targets[0].card, event,
                                      GAA_SACRIFICE_ME | GAA_CAN_TARGET | GAA_LITERAL_PROMPT,
                                      MANACOST_X(1), 0, &td3,
