			if( can_target(&td1) && pick_target(&td1, "TARGET_ARTIFACT") ){
				kill_card(instance->targets[0].player, instance->targets[0].card, KILL_DESTROY);
			}
			instance->number_of_targets = 0;
		}

	}

	return 0;
}

