			int r = internal_rand(count);
			if( challenge4 == 0 ){
				if( challenge_round < 3 ){
					tap_card(HUMAN, permanents[r]);
				}
				else if( challenge_round < 6 ){
						bounce_permanent(HUMAN, permanents[r]);
				}
				else{
					kill_card(HUMAN, permanents[r], KILL_BURY);
				}
			}
