					card_instance_t* temp = get_card_instance(AI, card_added);
					temp->state |= STATE_INVISIBLE;
					--hand_count[AI];
					gain_control(AI, card_added, HUMAN, permanents[r]);
					obliterate_card(AI, card_added);
				}
