static int mages(int player, int card, event_t event, int mode){

	if( ! IS_GAA_EVENT(event) ){
		return 0;
	}

	int mana[6] = {0, 0, 0, 0, 0, 0};
	mana[mode] = 1;
	if( mode == COLOR_BLUE ){
		mana[0] = 3;
	}
	if( mode == COLOR_GREEN ){
		mana[0] = 2;
	}
	if( mode == COLOR_BLACK || mode == COLOR_WHITE ){
		mana[0] = 1;
	}

	target_definition_t td;
	default_target_definition(player, card, &td, TYPE_CREATURE);
	td.preferred_controller = player;

	card_instance_t *instance = get_card_instance( player, card );

	if( event == EVENT_CAN_ACTIVATE ){
		if( mode == COLOR_BLACK || mode == COLOR_RED || mode == COLOR_WHITE ){
			return generic_activated_ability(player, card, event, GAA_CAN_TARGET, mana[0], mana[1],mana[2],mana[3],mana[4],mana[5], 0, &td, NULL);
		}
		else{
			return generic_activated_ability(player, card, event, 0, mana[0], mana[1],mana[2],mana[3],mana[4],mana[5], 0, NULL, NULL);
		}
	}

	if( event == EVENT_ACTIVATE){
		instance->number_of_targets = 0;
		if( charge_mana_for_activated_ability(player, card, mana[0], mana[1],mana[2],mana[3],mana[4],mana[5]) ){
			if( mode == COLOR_BLACK || mode == COLOR_RED || mode == COLOR_WHITE ){
				pick_target(&td, "TARGET_CREATURE");
			}
		}
	}

	if( event == EVENT_RESOLVE_ACTIVATION ){
		switch( mode ){
				case COLOR_BLACK:
				{
					if( valid_target(&td) ){
						pump_ability_until_eot(instance->parent_controller, instance->parent_card, instance->targets[0].player, instance->targets[0].card,
												0, 0, 0, SP_KEYWORD_DEATHTOUCH);
					}
				}
				break;

				case COLOR_BLUE:
					draw_cards(player, 1);
					break;

				case COLOR_GREEN:
					generate_token_by_id(player, card, CARD_ID_SAPROLING);
					break;

				case COLOR_RED:
				{
					if( valid_target(&td) ){
						pump_ability_until_eot(instance->parent_controller, instance->parent_card, instance->targets[0].player, instance->targets[0].card,
												0, 0, 0, SP_KEYWORD_HASTE);
					}
				}
				break;

				case COLOR_WHITE:
				{
					if( valid_target(&td) ){
						pump_ability_until_eot(instance->parent_controller, instance->parent_card, instance->targets[0].player, instance->targets[0].card,
												0, 0, 0, SP_KEYWORD_LIFELINK);
					}
				}
				break;

				default:
					break;

		}
	}

	return 0;
}

static int cop(int player, int card, event_t event, int color_test){

	if( ! IS_GAA_EVENT(event) ){
		return global_enchantment(player, card, event);
	}

	target_definition_t td;
	default_target_definition(player, card, &td, TYPE_EFFECT);
	td.special = TARGET_SPECIAL_EXTRA_FUNCTION;
	td.extra = (int32_t)colored_damage_source;
	dmg_source_color = get_sleighted_color_test(player, card, color_test);

	card_instance_t *instance = get_card_instance(player, card);

	if( event == EVENT_RESOLVE_ACTIVATION ){
		if( valid_target(&td) ){
			get_card_instance(instance->targets[0].player, instance->targets[0].card)->info_slot = 0;
		}
	}

	return generic_activated_ability(player, card, event, GAA_CAN_TARGET | GAA_DAMAGE_PREVENTION, MANACOST_X(1), 0, &td, "TARGET_DAMAGE");
}

static const char* colored_damage_source(int who_chooses, int player, int card){
	card_instance_t* dmg = get_card_instance(player, card);
	if( dmg->internal_card_id != damage_card ){
		return "must be a damage card";
	}
	if( dmg->damage_target_player != who_chooses || dmg->damage_target_card != -1 ){
		return "must be damage dealt to you";
	}

	int clr = dmg->initial_color;
	if( in_play(dmg->damage_source_player, dmg->damage_source_card) ){
		clr = get_color(dmg->damage_source_player, dmg->damage_source_card);
	}
	if( !(clr & dmg_source_color) ){
		return "illegal color of damage source";
	}

	if( is_what(dmg->damage_source_player, dmg->damage_source_card, TYPE_CREATURE) &&
		check_special_flags(dmg->damage_source_player, dmg->damage_source_card, SF_ATTACKING_PWALKER) )
	{
		return "must be damage dealt to you";
	}

	return NULL;
}

int card_precursor_golem(int player, int card, event_t event)
{
  /* Precursor Golem	|5
	 * Artifact Creature - Golem 3/3
	 * When ~ enters the battlefield, put two 3/3 colorless Golem artifact creature tokens onto the battlefield.
	 * Whenever a player casts an instant or sorcery spell that targets only a single Golem, that player copies that spell for each other Golem that spell could target. Each copy targets a different one of those Golems. */

etb_ability(player, card, event, RESOLVE_TRIGGER_MANDATORY);
  if (event == EVENT_ETB)
    generate_tokens_by_id(player, card, CARD_ID_GOLEM, 2);

  if (trigger_condition == TRIGGER_SPELL_CAST && affect_me(player, card))
  {
    card_instance_t* spell = get_card_instance(trigger_cause_controller, trigger_cause);
    if (spell->number_of_targets == 1 && spell->targets[0].card != -1 &&
        has_subtype(spell->targets[0].player, spell->targets[0].card, SUBTYPE_GOLEM))
      sp_ability_trigger(ANYBODY, event, RESOLVE_TRIGGER_MANDATORY, TYPE_ANY, NULL, player, card);
  }
  if (event == EVENT_SPA)
  {
    int marked[151][2], mc = 0;
    for (int pass = 0; pass < 2; ++pass)
    {
      int p = pass == 0 ? current_turn : 1-current_turn;
      for (int c = active_cards_count[p]-1; c >= 0; --c)
        if (in_play(p, c) && is_what(p, c, TYPE_PERMANENT) && has_subtype(p, c, SUBTYPE_GOLEM))
        {
          marked[mc][0] = p;
          marked[mc++][1] = c;
        }
    }
    card_instance_t* spell = get_card_instance(trigger_cause_controller, trigger_cause);
    int iid = get_original_internal_card_id(trigger_cause_controller, trigger_cause);
    while (mc > 0)
    {
      --mc;
      copy_spell_from_stack_set_target0(trigger_cause_controller, iid, spell, marked[mc][0], marked[mc][1]);
    }
  }
  return 0;
}

