	enum{
		CHOICE_MANA = 1,
		CHOICE_GET_BACK_YOUR_PERMANENTS
	};

	if (event == EVENT_ACTIVATE){
		int choice = CHOICE_MANA;
		int ab2 = generic_activated_ability(player, card, EVENT_CAN_ACTIVATE, GAA_UNTAPPED, MANACOST0, 0, NULL, NULL);
		if( !paying_mana() && ab2 ){
