								"Exile from graveyard", count_graveyard(player) > 1, 5,
								"Sac an artifact", can_sacrifice_type_as_cost(player, 1, TYPE_ARTIFACT), 1);

			if( ! choice ){
				spell_fizzled = 1;
				return 0;
