					cancel = 1;
				}
			}
		}
	}

	if( event == EVENT_RESOLVE_ACTIVATION ){
		card_instance_t* instance = get_card_instance(player, card);
		int p = instance->parent_controller, c = instance->parent_card;
		if (in_play(p, c)){
			pump_until_eot_merge_previous(p, c, p, c, 1, 1);
		}
	}

	return 0;
}

