									break;
								}
							}
							if( ! found ){
								exiled[ec] = iid;
								ec++;
							}
						}
					}
					count--;
			}
			int choice = 0;
			if( player == HUMAN ){
				choice = do_dialog(player, player, card, -1, -1, " Remove All Matches\n Manually Pick Cards", 0);
			}
