	 * Land
	 * |T: Add |1 to your mana pool.
	 * |T, Sacrifice ~: Put your commander into your hand from the command zone. */


	if( ! IS_GAA_EVENT(event) || event == EVENT_CAN_ACTIVATE ){
		return mana_producer(player, card, event);
	}

	enum
	{
