					}
					else{
						if( life_bid[1-bid_turn] >= life[bid_turn] ){
							life_bid[bid_turn] = 0;
						}
						else{
							if( check_battlefield_for_id(bid_turn, CARD_ID_PLATINUM_EMPERION) ){
