					  if (player == AI)
						ai_modifier -= 128;
					}
				  else
					gain_control(player, card, instance->targets[0].player, instance->targets[0].card);
				}
			  break;

			case CHOICE_EMBLEM:
			  generate_token_by_id(player, card, CARD_ID_DACKS_EMBLEM);
			  break;
		  }
	}

  return planeswalker(player, card, event, 3);
}

