					effect_act_of_treason(1-player, fake, player, c);
				}
			}
			obliterate_card(1-player, fake);
		}
		kill_card(player, card, KILL_DESTROY);
	}

	return generic_spell(player, card, event, GS_CAN_ONLY_TARGET_OPPONENT, &td, NULL, 1, NULL);
}

