		default_target_definition(player, card, &td, TYPE_CREATURE);

		enum
		{
			CHOICE_EXILE = 1,
			CHOICE_SUCK_LIFE,
			CHOICE_DISCARD_DRAW
		};

		if( event == EVENT_ACTIVATE ){
			instance->number_of_targets = instance->info_slot = 0;

			int priority_exile = count_counters(player, card, COUNTER_LOYALTY) < 2 ? 35 : 5;
