		CYCLE_ALL_CARDS(p, c, 	{
									if( in_play(p, c) && is_what(p, c, TYPE_ARTIFACT) ){
										int this_cmc = get_cmc(p, c);
										if( this_cmc < min_cmc ){
											min_cmc = this_cmc;
										}
