					int amount = count_subtype(player, TYPE_CREATURE, -1);
					if (amount > 0){
						do {
							spell_fizzled = 0;
							produce_mana_any_combination_of_colors(player, COLOR_TEST_RED|COLOR_TEST_GREEN, amount, NULL);
						} while (spell_fizzled == 1);
					}
				}
				break;

