					generate_token(&token);
				}
				break;

				case CHOICE_EXILE7:
				{
					int amount = MIN(7, count_deck(player));
					if( amount > 0 ){
						int *deck = deck_ptr[player];
						show_deck( 1-player, deck, amount, "Card exiled by Xenagos", 0, 0x7375B0 );

