	card_instance_t *instance = get_card_instance(player, card);

	enum{
		CHOICE_LIFELINK = 1,
		CHOICE_DRAW,
		CHOICE_REMOVE_CRIT
	};

	if( event == EVENT_CAN_CAST ){
		return basic_spell(player, card, event);
