	}

	if( event == EVENT_RESOLVE_SPELL ){
		if( instance->info_slot == CHOICE_LIFELINK ){
			pump_subtype_until_eot(player, card, player, -1, 0, 0, 0, SP_KEYWORD_LIFELINK);
