		if( instance->info_slot == CHOICE_DRAW ){
			draw_cards(player, 1);
		}
		if( instance->info_slot == CHOICE_REMOVE_CRIT && valid_target(&td) ){
			put_on_top_of_deck(instance->targets[0].player, instance->targets[0].card);
