	default_target_definition(player, card, &td, TYPE_ANY);
	td.extra = damage_card;
	td.special = TARGET_SPECIAL_DAMAGE_CREATURE;
	card_instance_t *instance = get_card_instance(player, card);
	if (event == EVENT_ACTIVATE){
