		if (num_validated == 0 && num_targets > 0){
			spell_fizzled = 1;
		}
		else{
			int result = cantrip(player, card, 1);
			card_instance_t *leg = get_card_instance(player, result);
			leg->targets[1].player = instance->targets[0].player;
		}
	}

	return 0;
}

