			if( ! new_pick_target(&td, "TARGET_LAND", 0, 1) ){
				return 0;
			}
		}
		if( choice == CHOICE_RETURN_PERMANENT ){
			if(	select_target_from_grave_source(player, card, player, 0, AI_MAX_VALUE, &test, 0) == -1 ){
