			  int iid = *loc & ~0x80000000;
			  add_card_to_hand(owner, iid);
			  remove_card_from_rfg(owner, cards_data[iid].id);
			  *loc = -1;
			}

		  exiledby_destroy_detached(player, instance->targets[0].player);
		  break;
	  }

  return 0;
}

