			pump_subtype_until_eot(player, card, ANYBODY, -1, -1, -1, 0, 0);
		}
		if( instance->info_slot == CHOICE_KILL_ENCHANTMENT && valid_target(&td) ){
			kill_card(instance->targets[0].player, instance->targets[0].card, KILL_DESTROY);
