				rfg_top_card_of_deck(p);
				if( ! is_what(-1, iid, TYPE_LAND) && can_legally_play_iid(p, iid) ){
					char buffer [100];
					scnprintf(buffer, 100, "Play %s", cards_ptr[cards_data[iid].id]->name);
