					needle |= (instance->targets[1].player == 1 ? 0x80000000 : 0);
					if( exiledby_find(player, card, needle, &leg, &idx) != NULL ){
						return result;
					}
				}
			}
			else{
				if( player == HUMAN ){
					return 1;
				}
			}
		}
	}

