   * -10: Exile all cards from all opponents' hands and graveyards. */

  if (event == EVENT_CAST_SPELL && affect_me(player, card))
	ai_modifier += 48;

  if (event == EVENT_CAN_ACTIVATE || event == EVENT_ACTIVATE || event == EVENT_RESOLVE_ACTIVATION)
