	  default_target_definition(player, card, &td_opponent, 0);
	  td_opponent.zone = TARGET_ZONE_PLAYERS;
	  td_opponent.allowed_controller = 1 - player;

	  int can_library = can_target(&td_opponent);
	  int priority_library = 50;

