			}
			else{
				return 0;
			}
		}
		if( instance->info_slot & CHOICE_DAMAGE_OPP ){
			if( new_pick_target(&td2, "TARGET_OPPONENT_OR_PLANESWALKER", base_target, 1) ){
				base_target++;
			}
			else{
				return 0;
			}
		}
	}

	if( event == EVENT_RESOLVE_SPELL ){
		int base_target = 0;
		if( instance->info_slot & CHOICE_DISCARD_DRAW ){
