			  break;
		  }

	  if (tgts > 0 && valid_tgts == 0)
		cancel = 1;
	  else
		for (choice = 0; choice < 2; ++choice)
		  switch (choices[choice])
			{
			  case CHOICE_INVALID_TARGET:
				break;

			  case CHOICE_RESURRECT:
				reanimate_permanent(player, card, player, inst->targets[2].player, REANIMATE_DEFAULT);
