		int abilities[5];
		int i;
		for(i=1; i<6; i++){
			abilities[i-1] = 0;
			if( has_mana_for_activated_ability(player, card, MANACOST_X(i)) ){
				if( i == CHOICE_UNTAP ){
					abilities[i-1] = 1;
				}
				if( ! is_tapped(player, card) ){
					if( i == CHOICE_GAIN_LIFE || i == CHOICE_DRAW ){
						abilities[i-1] = 1;
