		};
		int current_abilities = get_abilities(player, card, EVENT_ABILITIES, -1);
		if( instance->targets[1].card > -1 ){
			current_abilities |= instance->targets[1].card;
		}
		int priorities[4] = {
							0,
							current_phase == PHASE_AFTER_BLOCKING ? 10 : 1,
