		} else if (target_1_valid){
			tap_card(instance->targets[1].player, instance->targets[1].card);
		} else {
			spell_fizzled = 1;
		}

		get_card_instance(instance->parent_controller, instance->parent_card)->number_of_targets = 0;
		return 0;
	}

	return 0;
}

