			int result = will_of_the_council(player, card, pos1, pos2, ai_priorities);
			vote[0]+=BYTE0(result);
			vote[1]+=BYTE1(result);

			if( vote[0] > vote[1] ){
				real_counter_a_spell(player, card, instance->targets[0].player, instance->targets[0].card);
