			default_target_definition(player, card, &td3, TYPE_ARTIFACT);
			if( count_graveyard_by_type(player, TYPE_ARTIFACT) > 0 && target_available(player, card, &td0) && ! graveyard_has_shroud(player) ){
				td3 = td0;
